export async function resolve(input,api) {
  const response=await api.request({url:'https://json.example.com/api/list',method:'POST',body:{url:input.url,directory:input.directory?.id??'',cursor:input.cursor??'',query:input.query??''}});
  return JSON.parse(response.text);
}
export const list=resolve;
export const search=resolve;
export function detail(input){return {title:input.resource.name,description:'文件详情'};}
export async function download(input,api){
  const response=await api.request({url:'https://json.example.com/api/download',method:'POST',body:{id:input.resource.id,token:input.state.token,version:'v1'}});
  return JSON.parse(response.text);
}

export async function resolve(input,api){
  const response=await api.request({url:input.url});
  const page=await api.html(response.text,{files:{selector:'a.download',attributes:['href']}});
  const items=[];
  for(const [i,row] of page.files.entries())items.push({id:String(i),name:row.text,kind:'file',url:await api.codec('urlResolve',[input.url,row.href])});
  return {title:'HTML 文件索引',items};
}
export function download(input){return {urls:[input.resource.url]};}

import {canonical,sequence} from './shared.js';
export async function resolve(input,api){
  const signature=await api.crypto('hash',['sha256',canonical(input.url)]);
  const response=await api.request({url:'https://api.example.net/list',headers:{'X-Sign':signature}});
  const data=JSON.parse(response.text);
  return {title:'签名资源服务',items:data.files,state:{token:sequence()}};
}
export async function download(input,api){
  const signature=await api.crypto('hmac',['sha256',input.resource.id,input.state.token]);
  const response=await api.request({url:'https://api.example.net/download',method:'POST',headers:{'X-Sign':signature},body:{id:input.resource.id}});
  return JSON.parse(response.text);
}
